 Here's a Dart function that computes the top three coins with the highest average profit and the top three coins with the highest average loss based on the given list of transaction objects:

```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, List<double>> calculateAverages({required List<Transaction> transactions}) {
  final Map<String, List<double>> coinProfitLoss = {};

  for (final transaction in transactions) {
    if (coinProfitLoss.containsKey(transaction.coinName)) {
      coinProfitLoss[transaction.coinName]!.add(transaction.profitLoss);
    } else {
      coinProfitLoss[transaction.coinName] = [transaction.profitLoss];
    }
  }

  return coinProfitLoss;
}

List<dynamic> getTopCoins({required Map<String, List<double>> coinData, required bool isProfit}) {
  final sortedCoins = coinData.entries.map((entry) => MapEntry(entry.key, entry.value.reduce((a, b) => a + b) / entry.value.length)).toList();
  sortedCoins.sort((a, b) {
    final profitA = a.value;
    final profitB = b.value;
    return isProfit ? (profitB - profitA).abs() : (profitA - profitB).abs();
  });

  return sortedCoins.take(isProfit ? 3 : 6).map((mapEntry) => mapEntry.key).toList();
}

