const axios = require('axios'); // Import the required library for making HTTP requests

async function postMessageToSlack(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: {
        'Content-Type': 'application/json; charset=utf-8'
      },
      data: {
