    double refundAmount = 600.0; // Amount agreed upon by the seller for the refund

    // Calculate the total refund amount (purchase price minus residual value and refund amount)
    double totalRefund = purchasePrice - residualValue - refundAmount;

    // Calculate the percentage of the purchase price that is refunded
